total = 0
for i in range(1, 5):
    if i == 3:
        continue
    total += i
print(total)

def countdown(n):
    while n > 0:
        print(n)
        n = n
    print("done")

countdown(3)

exercises.solutionCode:
def countdown(n):
    while n > 0:
        print(n)
        n -= 1
    print("done")

countdown(3)
